interface PaymentGateway {
  charge(amount: number): Promise<void>;
}

abstract class PaymentCreator {
  // The Factory Method — subclasses decide what gets built
  abstract createGateway(): PaymentGateway;

  processPayment(amount: number) {
    const gateway = this.createGateway();
    return gateway.charge(amount);
  }
}

class StripeCreator extends PaymentCreator {
  createGateway(): PaymentGateway {
    return new StripeGateway();
  }
}

class RazorpayCreator extends PaymentCreator {
  createGateway(): PaymentGateway {
    return new RazorpayGateway();
  }
}

// Adding PayPal = one new file, PaymentCreator never changes
class PayPalCreator extends PaymentCreator {
  createGateway(): PaymentGateway {
    return new PayPalGateway();
  }
}
